a_boolean is_supported_ifc_version(an_ifc_version major_version,
                                   an_ifc_version minor_version)
/*
Given a major and minor IFC version number, return TRUE if the version is
supported, otherwise return FALSE.
*/
{
  a_boolean result = FALSE;

  switch (major_version) {
    case 0:
      switch (minor_version) {
        case 44:
        case 43:
        case 42:
        case 41:
        case 33:
          result = TRUE;
          break;
        default:
          break;
      }  /* switch */
      break;
    default:
      break;
  }  /* switch */
  return result;
}  /* is_supported_ifc_version */


