/*
Functions for interacting with IFC AccessSort sorts.
*/


a_const_char* str_for(an_ifc_access_sort universal)
/*
Given the universal representation of AccessSort, return the textual name in
the form of a c-string.
*/
{
  a_const_char *result;

  switch (universal) {
    case ifc_as_none:
      result = "AccessSort::None";
      break;
    case ifc_as_private:
      result = "AccessSort::Private";
      break;
    case ifc_as_protected:
      result = "AccessSort::Protected";
      break;
    case ifc_as_public:
      result = "AccessSort::Public";
      break;
    default:
      unexpected_condition_str("Invalid value for a AccessSort.");
      break;
  }  /* switch */
  return result;
}  /* str_for */


