      break;
    case ifc_ts_type_fundamental:
      result = ifc_pk_type_fundamental;
      break;
    case ifc_ts_type_lvalue_reference:
      result = ifc_pk_type_lvalue_reference;
      break;
    case ifc_ts_type_method:
      result = ifc_pk_type_nonstatic_member_function;
      break;
    case ifc_ts_type_placeholder:
